
DELETE FROM events WHERE created_at < 1794150300000 AND NOT ((kind = 'prompt' AND status = 'queued') OR status IN ('running', 'stopped'));
UPDATE events SET by_kind = 'remit' WHERE by_kind = 'mindchains';
UPDATE events SET tool_name = replace(replace(replace(tool_name, 'ask_human', 'ask_owner'), 'mcp__mindchains__', 'mcp__remit__'), 'mcp.mindchains.', 'mcp.remit.') WHERE tool_name LIKE '%mindchains%';
UPDATE events SET title = replace(replace(replace(title, 'ask_human', 'ask_owner'), 'mcp__mindchains__', 'mcp__remit__'), 'mcp.mindchains.', 'mcp.remit.') WHERE title LIKE '%mindchains%';
UPDATE events SET data = replace(replace(replace(data, '"kind":"mindchains"', '"kind":"remit"'), 'mcp__mindchains__', 'mcp__remit__'), 'mcp.mindchains.', 'mcp.remit.') WHERE typeof(data) = 'text' AND data LIKE '%mindchains%';
